/**
 * CloudApp 统一部署服务类型定义
 * 支持 static-hosting（静态托管）和 http-function（预留）两种部署类型
 *
 * 命名规范：
 * - 入参接口（IXxxParams）：camelCase，通过 upperCaseObjKey 转换后透传给 API
 * - 返回值接口（IXxxResult）：PascalCase，与 API 响应字段保持一致
 */
/**
 * 部署类型
 * - static-hosting: 静态托管部署
 * - http-function: HTTP 云函数部署（预留）
 * - custom: 自定义构建（CloudApp custom：源码 ZIP → 容器内执行 CustomSteps → docker build/push TCR），
 *   用于 HTTP 函数镜像的云端构建（buildStrategy: cloud）
 */
export type DeployType = 'static-hosting' | 'http-function' | 'custom';
/**
 * 构建类型
 * - GIT: 从 Git 仓库构建
 * - ZIP: 从 ZIP 包构建
 * - TEMPLATE: 从模板构建
 * - zip: custom 构建的源码 ZIP（与 API 文档 BuildType 大小写保持一致）
 */
export type BuildType = 'GIT' | 'ZIP' | 'TEMPLATE' | 'zip' | 'git';
/**
 * custom 构建源码来源
 *对应 API 的 Source 字段，zip 模式回填 DescribeCloudAppCosInfo 返回的时间戳
 */
export interface ICustomBuildSource {
    /** 源码类型，当前实现为 zip */
    type: 'zip' | 'git';
    /** COS 时间戳，原样使用 DescribeCloudAppCosInfo 返回的 UnixTimestamp */
    cosTimestamp?: string;
    /** COS 文件后缀，默认 .zip */
    cosSuffix?: string;
}
/** custom 构建环境变量项（明文，禁止写入敏感值） */
export interface ICustomBuildEnv {
    key: string;
    value: string;
}
/**
 * custom 构建密钥项
 * CloudApp 在构建容器中按 $SECRET_{NAME} 注入，Value 不应进入日志或普通环境变量。
 */
export interface ICustomBuildSecret {
    name: string;
    value: string;
}
/**
 * custom 构建自定义步骤
 * SDK 固定生成模板，用户不可控字段绝不作为任意 shell 片段拼接
 */
export interface ICustomBuildStep {
    name: string;
    command: string;
}
/**
 * custom 构建单步状态（API 响应，字段大小写与响应一致）
 * 注意：Duration 为字符串、Status 为小写
 */
export interface CloudAppBuildStep {
    Name: string;
    Status: string;
    Duration?: string;
    /** 失败时的退出码，用于定位 */
    ExitCode?: number;
}
/**
 * custom 构建产物（API 响应）
 * 镜像构建成功后Type 通常为 image
 */
export interface CloudAppArtifact {
    Type: string;
    Name: string;
    Status?: string;
    /** 部分场景直接回传完整镜像地址 */
    ImageUri?: string;
    /** 部分场景回传 digest */
    Digest?: string;
}
/**
 * 构建状态
 * custom 构建终态为 SUCCESS / FAILED / CANCELED
 */
export type BuildStatus = 'BUILDING' | 'SUCCESS' | 'FAILED' | 'CANCELED';
/**
 * 构建命令配置（入参）
 */
export interface IStaticCmd {
    buildCmd?: string;
    installCmd?: string;
    deployCmd?: string;
}
/**
 * 静态环境变量配置（入参）
 */
export interface IStaticEnv {
    variables?: Array<{
        key: string;
        value: string;
    }>;
}
/**
 * 静态托管配置（入参）
 */
export interface IStaticConfig {
    /** 框架类型：vue、react、nextjs 等 */
    framework?: string;
    /** Node.js 版本，默认 20 */
    nodeJsVersion?: string;
    /** 访问路径 */
    appPath?: string;
    /** 构建目录 */
    buildPath?: string;
    /** ZIP 文件地址（BuildType=ZIP/TEMPLATE 时使用） */
    zipFileUrl?: string;
    /** COS 时间戳（通过 uploadCode 上传后获取，BuildType=ZIP 时使用） */
    cosTimestamp?: string;
    /** COS 文件后缀 */
    cosSuffix?: string;
    /** 代码源平台：github、gitlab、gitee */
    codeSource?: string;
    /** 代码仓库 */
    codeRepo?: string;
    /** 代码分支 */
    codeBranch?: string;
    /** 构建命令配置 */
    staticCmd?: IStaticCmd;
    /** 构建环境变量 */
    staticEnv?: IStaticEnv;
}
/**
 * 静态托管构建命令配置（API 响应）
 */
export interface StaticCmd {
    BuildCmd?: string;
    InstallCmd?: string;
    DeployCmd?: string;
}
/**
 * 静态托管环境变量配置（API 响应，对应文档 StaticEnvironment）
 */
export interface StaticEnv {
    /** 环境变量数组，可能为 null */
    Variables?: Array<{
        Key: string;
        Value: string;
    }> | null;
}
/**
 * 静态托管配置（API 响应，对应文档 StaticConfig）
 * 被 CreateCloudApp、DescribeCloudAppVersion、DescribeCloudAppVersionList 引用
 * 注意：所有字段均可能返回 null
 */
export interface CloudAppStaticConfig {
    /** 框架类型：vue、react、nextjs 等 */
    Framework?: string | null;
    /** Node.js 版本，默认 20 */
    NodeJsVersion?: string | null;
    /** 访问路径 */
    AppPath?: string | null;
    /** 构建目录 */
    BuildPath?: string | null;
    /** ZIP 文件地址（BuildType=ZIP/TEMPLATE 时使用） */
    ZipFileUrl?: string | null;
    /** COS 时间戳 */
    CosTimestamp?: string | null;
    /** COS 文件后缀 */
    CosSuffix?: string | null;
    /** 代码源平台：github、gitlab、gitee */
    CodeSource?: string | null;
    /** 代码仓库 */
    CodeRepo?: string | null;
    /** 代码分支 */
    CodeBranch?: string | null;
    /** 构建命令配置 */
    StaticCmd?: StaticCmd | null;
    /** 构建环境变量 */
    StaticEnv?: StaticEnv | null;
}
/**
 * 应用列表项（API 响应 CloudAppServiceItem）
 */
export interface CloudAppServiceItem {
    ServiceName: string;
    DeployType: string;
    Framework?: string;
    Domain?: string;
    AppPath?: string;
    CreateTime: string;
    LatestVersionName?: string;
    LatestStatus?: string;
    LatestBuildTime?: string;
}
/** @deprecated 请使用 CloudAppServiceItem */
export type CloudAppItem = CloudAppServiceItem;
/**
 * 版本信息（API 响应 CloudAppVersionItem）
 */
export interface CloudAppVersion {
    VersionName: string;
    BuildId: string;
    BuildType?: string;
    Status: string;
    Framework?: string;
    BuildTime?: string;
    StaticConfig?: CloudAppStaticConfig;
}
export interface ICreateCloudAppParams {
    /** 环境 ID（可选，默认从 Environment 获取） */
    envId?: string;
    /** 部署类型：static-hosting / http-function / custom */
    deployType: DeployType;
    /** 服务名称 */
    serviceName: string;
    /** 构建类型：GIT / ZIP / TEMPLATE / zip / git */
    buildType?: BuildType;
    /** 静态托管配置（deployType 为 static-hosting 时使用） */
    staticConfig?: IStaticConfig;
    /** custom 构建源码来源（deployType 为 custom 时使用） */
    source?: ICustomBuildSource;
    /** custom 构建环境变量（deployType 为 custom 时使用，禁止敏感值） */
    env?: ICustomBuildEnv[];
    /** custom 构建密钥（deployType 为 custom 时使用） */
    secrets?: ICustomBuildSecret[];
    /** custom 构建自定义步骤（deployType 为 custom 时使用，SDK 固定模板） */
    customSteps?: ICustomBuildStep[];
    /** 跳过云端构建（纯静态直传场景：产物已直传，仅写部署记录，对应 API SkipBuild） */
    skipBuild?: boolean;
}
export interface ICreateCloudAppResult {
    ServiceName: string;
    BuildId: string;
    VersionName: string;
    RequestId: string;
}
export interface IDescribeCloudAppListParams {
    /** 环境 ID（可选） */
    envId?: string;
    /** 部署类型 */
    deployType: DeployType;
    /** 页码（从 1 开始） */
    pageNo?: number;
    /** 每页大小 */
    pageSize?: number;
    /** 搜索关键字，按应用名模糊搜索 */
    searchKey?: string;
}
export interface IDescribeCloudAppListResult {
    Total: number;
    ServiceList: CloudAppServiceItem[];
    RequestId: string;
}
export interface IDescribeCloudAppInfoParams {
    /** 环境 ID（可选） */
    envId?: string;
    /** 部署类型 */
    deployType: DeployType;
    /** 服务名称 */
    serviceName: string;
}
export interface IDescribeCloudAppInfoResult {
    ServiceName: string;
    DeployType: string;
    Framework?: string;
    Domain?: string;
    AppPath?: string;
    CreateTime: string;
    LatestVersionName?: string;
    LatestStatus?: string;
    LatestBuildTime?: string;
    RequestId: string;
}
export interface IDeleteCloudAppParams {
    /** 环境 ID（可选） */
    envId?: string;
    /** 部署类型 */
    deployType: DeployType;
    /** 服务名称 */
    serviceName: string;
}
export interface IDeleteCloudAppResult {
    Result: boolean;
    RequestId: string;
}
export interface IDescribeCloudAppVersionParams {
    /** 环境 ID（可选） */
    envId?: string;
    /** 部署类型 */
    deployType: DeployType;
    /** 服务名称 */
    serviceName: string;
    /** 版本名称（与 buildId 二选一） */
    versionName?: string;
    /** 构建 ID（与 versionName 二选一） */
    buildId?: string;
}
export interface IDescribeCloudAppVersionResult {
    BuildType: string;
    BuildId: string;
    Status: BuildStatus;
    Framework?: string;
    StaticConfig?: CloudAppStaticConfig;
    BuildTime?: string;
    /** custom 构建的分步状态（deployType 为 custom 时返回） */
    Steps?: CloudAppBuildStep[] | null;
    /** custom 构建产物（deployType 为 custom 时返回，镜像信息优先从此获取） */
    Artifacts?: CloudAppArtifact[] | null;
    RequestId: string;
}
export interface IDescribeCloudAppVersionListParams {
    /** 环境 ID（可选） */
    envId?: string;
    /** 部署类型 */
    deployType: DeployType;
    /** 服务名称 */
    serviceName: string;
    /** 页码（从 1 开始） */
    pageNo?: number;
    /** 每页大小 */
    pageSize?: number;
}
export interface IDescribeCloudAppVersionListResult {
    Total: number;
    VersionList: CloudAppVersion[] | null;
    RequestId: string;
}
export interface IDeleteCloudAppVersionParams {
    /** 环境 ID（可选） */
    envId?: string;
    /** 部署类型 */
    deployType: DeployType;
    /** 服务名称 */
    serviceName: string;
    /** 版本名称 */
    versionName: string;
}
export interface IDeleteCloudAppVersionResult {
    Result: boolean;
    RequestId: string;
}
export interface IDescribeCloudAppCosInfoParams {
    /** 环境 ID（可选） */
    envId?: string;
    /** 部署类型 */
    deployType: DeployType;
    /** 服务名称 */
    serviceName: string;
    /** Unix 时间戳（用于指定文件路径，不传则自动生成） */
    unixTimestamp?: string;
    /** 文件后缀（默认 .zip） */
    suffix?: string;
    /** 是否需要下载 URL */
    needDownload?: boolean;
}
export interface CosHeader {
    Key: string;
    Value: string;
}
export interface IDescribeCloudAppCosInfoResult {
    UploadUrl: string;
    UploadHeaders?: CosHeader[];
    DownloadUrl?: string;
    DownloadHeaders?: CosHeader[];
    UnixTimestamp: string;
    RequestId: string;
}
/**
 * 上传进度信息
 */
export interface IProgressData {
    loaded: number;
    total: number;
    percent: number;
}
/**
 * 代码上传的分步阶段
 */
export type UploadPhase = 'pack' | 'credential' | 'read' | 'upload';
/**
 * 单个阶段计时信息（由 uploadCode 的 onPhase 回调触发）
 */
export interface IUploadPhaseTiming {
    /** 阶段名 */
    phase: UploadPhase;
    /** 耗时(ms) */
    durationMs: number;
    /** 字节数（pack: zip 大小; read/upload: buffer 大小） */
    bytes?: number;
}
/**
 * 上传代码参数
 */
export interface IUploadCloudAppCodeParams {
    /** 部署类型 */
    deployType: DeployType;
    /** 服务名称 */
    serviceName: string;
    /** 本地文件夹路径 */
    localPath: string;
    /** 忽略的文件/目录模式（追加到内置默认规则之后） */
    ignore?: string[];
    /**
     * 是否排除 node_modules：
     * 默认 true（静态产物 / 版本快照场景，避免误传大目录）；
     * 云端构建（需云端 install）场景设为 false，允许私有/离线依赖随源码包上传
     */
    excludeNodeModules?: boolean;
    /** 进度回调 */
    onProgress?: (progress: IProgressData) => void;
    /** 分步计时回调（各阶段完成时触发，用于 verbose 模式输出耗时） */
    onPhase?: (timing: IUploadPhaseTiming) => void;
}
/**
 * 上传代码结果
 */
export interface IUploadCloudAppCodeResult {
    /** COS 时间戳（用于 createApp 时传入 staticConfig.cosTimestamp） */
    cosTimestamp: string;
    /** Unix 时间戳（与 cosTimestamp 相同） */
    unixTimestamp: string;
}
